changeSet.sql:
UPDATE cms_block SET block_key = 'brands.appella.heroBanner', updated_at = CURRENT_TIMESTAMP WHERE block_key = 'brands.apella.heroBanner';
UPDATE cms_block SET link_target = replace(link_target, '/brands/apella', '/brands/appella'), updated_at = CURRENT_TIMESTAMP WHERE link_target LIKE '%/brands/apella%';
UPDATE cms_banner SET link_url = replace(link_url, '/brands/apella', '/brands/appella') WHERE link_url LIKE '%/brands/apella%';
UPDATE cms_block_translation AS translation SET title = replace(replace(replace(title, 'Apella', 'Appella'), 'APELLA', 'APPELLA'), 'apella', 'appella'), subtitle = replace(replace(replace(subtitle, 'Apella', 'Appella'), 'APELLA', 'APPELLA'), 'apella', 'appella'), description = replace(replace(replace(description, 'Apella', 'Appella'), 'APELLA', 'APPELLA'), 'apella', 'appella'), button_text = replace(replace(replace(button_text, 'Apella', 'Appella'), 'APELLA', 'APPELLA'), 'apella', 'appella'), alt_text = replace(replace(replace(alt_text, 'Apella', 'Appella'), 'APELLA', 'APPELLA'), 'apella', 'appella') FROM cms_block block WHERE translation.block_id = block.id AND block.block_key = 'brands.appella.heroBanner';

INSERT INTO cms_media (storage_type, public_url, original_filename, content_type, size_bytes) SELECT 'PUBLIC_PATH', seed.public_url, seed.original_filename, 'image/png', 0 FROM (VALUES ('/contact-banner-catalog.png', 'contact-banner-catalog.png'), ('/contact-banner-about-page.png', 'contact-banner-about-page.png') ) AS seed(public_url, original_filename) WHERE NOT EXISTS ( SELECT 1 FROM cms_media media WHERE media.storage_type = 'PUBLIC_PATH' AND media.public_url = seed.public_url );
WITH media AS ( SELECT id FROM cms_media WHERE storage_type = 'PUBLIC_PATH' AND public_url = '/contact-banner-catalog.png' ORDER BY id LIMIT 1 ) UPDATE cms_block SET media_id = media.id, media_kz_id = media.id, media_en_id = media.id, mobile_media_id = media.id, mobile_media_kz_id = media.id, mobile_media_en_id = media.id, updated_at = CURRENT_TIMESTAMP FROM media WHERE cms_block.block_key = 'catalog.contactBanner';
WITH media AS ( SELECT id FROM cms_media WHERE storage_type = 'PUBLIC_PATH' AND public_url = '/contact-banner-about-page.png' ORDER BY id LIMIT 1 ) UPDATE cms_block SET media_id = media.id, media_kz_id = media.id, media_en_id = media.id, mobile_media_id = media.id, mobile_media_kz_id = media.id, mobile_media_en_id = media.id, updated_at = CURRENT_TIMESTAMP FROM media WHERE cms_block.block_key = 'about.cooperationBanner';
